// ==UserScript==
// @name         YouTube Priority Caption Selector
// @namespace    https://github.com/andris155/YouTubePriorityCaptionSelector
// @version      1.0.0
// @description  Automatically selects YouTube captions based on your custom language priority list (manual & auto-generated), with intelligent auto-translate fallback and zero player flickering.
// @author       andris155
// @license      MIT
// @icon         https://www.google.com/s2/favicons?sz=64&domain=youtube.com
// @homepageURL  https://github.com/andris155/YouTubePriorityCaptionSelector
// @supportURL   https://github.com/andris155/YouTubePriorityCaptionSelector/issues
// @updateURL    https://raw.githubusercontent.com/andris155/YouTubePriorityCaptionSelector/main/YouTube%20Priority%20Caption%20Selector.user.js
// @downloadURL  https://raw.githubusercontent.com/andris155/YouTubePriorityCaptionSelector/main/YouTube%20Priority%20Caption%20Selector.user.js
// @match        https://www.youtube.com/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    const CONFIG = {
        /**
         * PRIORITY LIST:
         * Add as many or as few priority rules as you want (2, 3, 4, 5, or more).
         * The script checks them in order from top to bottom and activates the first match.
         *
         * Fields per rule:
         * - lang: (Required) ISO 639-1 language code (e.g. 'hu', 'en', 'de', 'es', 'fr', 'ja')
         * - autoGenerated: (Optional)
         *       false          = strictly human/manual captions only
         *       true           = strictly auto-generated (ASR) captions only
         *       omitted / null = accept either (prefers manual first if both exist)
         * - name: (Optional) Custom label for debug logging
         */
        PRIORITY: [
            // Priority 1: Hungarian manual captions
            { lang: 'hu', autoGenerated: false, name: 'Hungarian (Manual)' },
            // Priority 2: English manual captions
            { lang: 'en', autoGenerated: false, name: 'English (Manual)' },
            // Priority 3: Hungarian auto-generated captions
            { lang: 'hu', autoGenerated: true,  name: 'Hungarian (Auto-generated)' },
            // Priority 4: English auto-generated captions
            { lang: 'en', autoGenerated: true,  name: 'English (Auto-generated)' }
        ],

        // Target language for auto-translation if none of your priority options match.
        // Set to null or '' to disable auto-translation fallback.
        AUTO_TRANSLATE_TARGET: 'en',

        // Shorts Auto-Disable (default: off):
        // When set to true, automatically turns captions OFF if they are on for Shorts.
        DISABLE_ON_SHORTS: false,

        // "Native Language" Auto-Disable (default: off):
        // When enabled, automatically turns captions OFF if the video's original audio
        // matches one of your specified native languages.
        NATIVE_LANG_AUTO_DISABLE: {
            enabled: false,
            languages: ['hu'] // e.g. ['hu'] or ['hu', 'en']
        },

        // Channel Blacklist (default: off):
        // Automatically turns captions OFF for videos from specific channels (e.g. music, ASMR).
        // Supports channel names, @handles, or channel IDs (UC...).
        CHANNEL_BLACKLIST: {
            enabled: false,
            channels: [
                // Examples:
                // 'VEVO',
                // '@LofiGirl',
                // 'UC-lHJZR3Gqxm24_Vd_AJ5Yw'
            ]
        },

        // Channel Whitelist (default: off):
        // Always keeps captions enabled (bypassing Blacklist, Music Video, and Native Language Auto-Disable)
        // for specific channels. Supports channel names, @handles, or channel IDs (UC...).
        CHANNEL_WHITELIST: {
            enabled: false,
            channels: [
                // Examples:
                // 'Example Creator',
                // '@handle',
                // 'UC-lHJZR3Gqxm24_Vd_AJ5Yw'
            ]
        },

        // Smart "Music Video" Auto-Disable (default: off):
        // Automatically turns captions OFF for music videos, songs, and Topic tracks.
        DISABLE_ON_MUSIC: false,

        // "Smart Mute" Caption Trigger (default: off):
        // Automatically turns captions ON when the video is muted or volume is set to 0
        // (even on native language videos), and restores normal preference when unmuted.
        SMART_MUTE: false,

        // Manual Override Detection (default: on):
        // Pauses script interference for the current video if you manually toggle the CC button,
        // press 'C', or pick a caption track from YouTube's settings menu.
        RESPECT_MANUAL_OVERRIDE: true,

        CHANGE_DELAY: 600, // Settle delay (in ms) for YouTube's player initialization
        MAX_ATTEMPTS: 20,  // Max attempts while player is ready for target video (~6s)
        DEBUG: false
    };

    let processedVideoId = '';
    let manualOverrideVideoId = '';
    let lastTargetVideoId = '';
    let lastObservedUrl = location.href;
    let lastKnownCaptionState = '';
    let isScriptApplying = false;
    let pollInterval = null;
    let mountTimer = null;
    let lastMuteState = null;
    let smartMuteTurnedCaptionsOn = false;
    let isVolumeOrMuteChanging = false;
    const hookedPlayers = new WeakSet();

    function log(...args) {
        if (CONFIG.DEBUG) {
            console.log('[YT-Caption-Selector]', ...args);
        }
    }

    function clearMountTimer() {
        if (mountTimer) {
            clearTimeout(mountTimer);
            mountTimer = null;
        }
    }

    function clearPollInterval() {
        if (pollInterval) {
            clearInterval(pollInterval);
            pollInterval = null;
        }
    }

    function resetVideoState() {
        clearMountTimer();
        processedVideoId = '';
        manualOverrideVideoId = '';
        lastKnownCaptionState = '';
        lastMuteState = null;
        smartMuteTurnedCaptionsOn = false;
        isVolumeOrMuteChanging = false;
    }

    function isWatchPage() {
        const { pathname } = location;
        return pathname.startsWith('/watch') || pathname.startsWith('/shorts') || pathname.startsWith('/live');
    }

    function isShortsDisabled() {
        return Boolean(CONFIG.DISABLE_ON_SHORTS && location.pathname.startsWith('/shorts'));
    }

    function getTargetVideoId() {
        const { pathname, search } = location;
        const match = pathname.match(/^\/(?:shorts|live)\/([a-zA-Z0-9_-]+)/);
        if (match) return match[1];
        return new URLSearchParams(search).get('v') || '';
    }

    function getPlayer(targetVideoId) {
        if (targetVideoId) {
            const players = document.querySelectorAll('#movie_player, .html5-video-player');
            for (const p of players) {
                if (p.getVideoData?.()?.video_id === targetVideoId) {
                    return p;
                }
            }
        }

        // Tag-independent fallback for Shorts/multi-player layouts: find the visible/playing <video>
        const videos = document.querySelectorAll('video');
        let visibleFallback = null;
        for (const v of videos) {
            const rect = v.getBoundingClientRect();
            if (rect.width > 0 && rect.height > 0 && rect.top < window.innerHeight && rect.bottom > 0) {
                const container = v.closest('#movie_player, .html5-video-player');
                if (container) {
                    if (!v.paused) return container;
                    if (!visibleFallback) visibleFallback = container;
                }
            }
        }

        return visibleFallback ||
               document.querySelector('ytd-reel-video-renderer[is-active] #movie_player') ||
               document.getElementById('movie_player') ||
               document.querySelector('.html5-video-player');
    }

    function isPlayerMuted(player) {
        try {
            if (typeof player?.isMuted === 'function' && typeof player?.getVolume === 'function') {
                return player.isMuted() || player.getVolume() === 0;
            }
            if (typeof player?.isMuted === 'function') return player.isMuted();
            if (typeof player?.getVolume === 'function') return player.getVolume() === 0;
            const video = player?.querySelector?.('video') || document.querySelector('video');
            if (video) return video.muted || video.volume === 0;
        } catch {}
        return false;
    }

    function isMusicVideo(player, currentVideoId) {
        const response = getFreshPlayerResponse(player, currentVideoId);
        if (!response) return false;

        // 1. Check musicVideoType in videoDetails
        const musicType = response.videoDetails?.musicVideoType;
        if (typeof musicType === 'string' && musicType && musicType !== 'MUSIC_VIDEO_TYPE_UNSPECIFIED') {
            return true;
        }

        // 2. Check category in playerMicroformatRenderer
        const category = response.microformat?.playerMicroformatRenderer?.category;
        if (typeof category === 'string' && category.toLowerCase() === 'music') {
            return true;
        }

        // 3. Check author ending with " - Topic" (official auto-generated music artist channels)
        const author = response.videoDetails?.author || player?.getVideoData?.()?.author || '';
        if (author.endsWith(' - Topic')) {
            return true;
        }

        return false;
    }

    function isAutoGenerated(track) {
        const kind = (track.kind || '').toLowerCase();
        const vssId = track.vssId || '';
        const displayName = track.displayName || track.name?.simpleText || '';

        return (
            kind === 'asr' ||
            /(?:^|\.)a\./i.test(vssId) ||
            /auto|automat/i.test(displayName)
        );
    }

    function matchesLanguage(track, targetLang) {
        const lang = track.languageCode;
        if (!lang) return false;
        const lower = lang.toLowerCase();
        return lower === targetLang || lower.startsWith(`${targetLang}-`);
    }

    function findMatchingTrack(tracks, rule) {
        if (!rule || !rule.lang) return null;

        const langMatches = tracks.filter(t => matchesLanguage(t, rule.lang));
        if (!langMatches.length) return null;

        if (typeof rule.autoGenerated === 'boolean') {
            return langMatches.find(t => isAutoGenerated(t) === rule.autoGenerated) || null;
        }

        // If autoGenerated is not explicitly specified, prefer manual first, then auto-generated
        return langMatches.find(t => !isAutoGenerated(t)) || langMatches[0];
    }

    function getFreshPlayerResponse(player, currentVideoId) {
        try {
            const response = player?.getPlayerResponse?.();
            if (response?.videoDetails?.videoId === currentVideoId) {
                return response;
            }
        } catch {}

        if (window.ytInitialPlayerResponse?.videoDetails?.videoId === currentVideoId) {
            return window.ytInitialPlayerResponse;
        }

        return null;
    }

    function extractLangFromTrackId(id) {
        if (!id || typeof id !== 'string') return '';
        const prefix = id.split('.')[0].trim().toLowerCase();
        if (!prefix || prefix === 'default' || prefix === 'und' || prefix === 'zxx') return '';
        return /^[a-z]{2,3}(?:-[a-z0-9]{2,4})*$/.test(prefix) ? prefix : '';
    }

    function getVideoAudioLanguage(player, currentVideoId, tracks = []) {
        try {
            const currentAudio = player?.getAudioTrack?.();
            if (currentAudio?.languageCode) {
                return currentAudio.languageCode.toLowerCase();
            }
            const idLang = extractLangFromTrackId(currentAudio?.id);
            if (idLang) return idLang;
        } catch {}

        const response = getFreshPlayerResponse(player, currentVideoId);
        if (response) {
            const explicitLang = response.videoDetails?.defaultAudioLanguage ||
                                 response.videoDetails?.audioLanguage ||
                                 response.microformat?.playerMicroformatRenderer?.defaultAudioLanguage ||
                                 response.microformat?.playerMicroformatRenderer?.audioLanguage;
            if (typeof explicitLang === 'string' && explicitLang) {
                return explicitLang.toLowerCase();
            }

            const adaptiveFormats = response.streamingData?.adaptiveFormats;
            if (Array.isArray(adaptiveFormats)) {
                const defaultAudio = adaptiveFormats.find(f => f.audioTrack?.audioIsDefault && f.audioTrack?.id) ||
                                     adaptiveFormats.find(f => f.audioTrack?.id);
                const streamLang = extractLangFromTrackId(defaultAudio?.audioTrack?.id);
                if (streamLang) return streamLang;
            }
        }

        // Fallback for standard single-audio videos:
        // 1. ASR (auto-generated) track language reflects the actual spoken audio
        // 2. If no ASR exists and all caption tracks share a single language, use that language
        if (Array.isArray(tracks) && tracks.length) {
            const asrTrack = tracks.find(t => isAutoGenerated(t) && t.languageCode);
            if (asrTrack) {
                return asrTrack.languageCode.toLowerCase();
            }

            const baseLangs = new Set(
                tracks
                    .map(t => t.languageCode?.split('-')[0].toLowerCase())
                    .filter(Boolean)
            );
            if (baseLangs.size === 1) {
                return [...baseLangs][0];
            }
        }

        return '';
    }

    function isNativeAudioLanguage(audioLang, nativeLanguages) {
        if (!audioLang || !Array.isArray(nativeLanguages) || !nativeLanguages.length) return false;
        const lowerAudio = audioLang.toLowerCase();
        return nativeLanguages.some(native => {
            if (!native || typeof native !== 'string') return false;
            const lowerNative = native.trim().toLowerCase();
            return lowerAudio === lowerNative || lowerAudio.startsWith(`${lowerNative}-`);
        });
    }

    function getVideoChannelInfo(player, currentVideoId) {
        let author = player?.getVideoData?.()?.author || '';
        let channelId = '';
        let handle = '';

        const response = getFreshPlayerResponse(player, currentVideoId);
        if (response?.videoDetails) {
            author = author || response.videoDetails.author || '';
            channelId = response.videoDetails.channelId || '';
            const ownerUrl = response.microformat?.playerMicroformatRenderer?.ownerProfileUrl || '';
            const handleMatch = ownerUrl.match(/@([a-zA-Z0-9_.-]+)/);
            if (handleMatch) {
                handle = `@${handleMatch[1]}`;
            }
        }

        if (!handle) {
            const domChannelLink = document.querySelector(
                'ytd-reel-video-renderer[is-active] a[href*="/@"], ytd-watch-metadata a[href*="/@"], #above-the-fold a[href*="/@"], #owner a[href*="/@"]'
            );
            if (domChannelLink?.href) {
                const handleMatch = domChannelLink.href.match(/@([a-zA-Z0-9_.-]+)/);
                if (handleMatch) {
                    handle = `@${handleMatch[1]}`;
                }
            }
        }

        return {
            author: author.trim(),
            channelId: channelId.trim(),
            handle: handle.trim()
        };
    }

    function matchesChannelList(channelInfo, channelList) {
        if (!channelInfo || !Array.isArray(channelList) || !channelList.length) return false;

        const authorLower = channelInfo.author.toLowerCase();
        const idLower = channelInfo.channelId.toLowerCase();
        const handleLower = channelInfo.handle.toLowerCase();

        return channelList.some(entry => {
            if (!entry || typeof entry !== 'string') return false;
            const clean = entry.trim().toLowerCase();
            if (!clean) return false;

            return (
                (authorLower && authorLower === clean) ||
                (idLower && idLower === clean) ||
                (handleLower && (handleLower === clean || handleLower === `@${clean.replace(/^@/, '')}`))
            );
        });
    }

    function hasNoCaptionsAvailable(player, currentVideoId) {
        const response = getFreshPlayerResponse(player, currentVideoId);
        if (!response) return false;
        if (!response.captions) return true;
        const tracks = response.captions.playerCaptionsTracklistRenderer?.captionTracks;
        return Array.isArray(tracks) && tracks.length === 0;
    }

    function getAvailableTracks(player, currentVideoId) {
        let tracks = [];

        try {
            tracks = player.getOption?.('captions', 'tracklist') || [];
            if (!tracks.length) {
                player.loadModule?.('captions');
                tracks = player.getOption?.('captions', 'tracklist') || [];
            }
        } catch {}

        if (!tracks.length) {
            const response = getFreshPlayerResponse(player, currentVideoId);
            tracks = response?.captions?.playerCaptionsTracklistRenderer?.captionTracks || [];
        }

        return Array.isArray(tracks) ? tracks : [];
    }

    function getTranslationLanguageObject(player, currentVideoId, targetLang) {
        let translationLangs = [];

        try {
            translationLangs = player.getOption?.('captions', 'translationLanguages') || [];
        } catch {}

        if (!translationLangs.length) {
            const response = getFreshPlayerResponse(player, currentVideoId);
            translationLangs = response?.captions?.playerCaptionsTracklistRenderer?.translationLanguages || [];
        }

        const match = translationLangs.find(tl => tl.languageCode?.toLowerCase() === targetLang);

        if (match) {
            const name = match.languageName?.runs?.[0]?.text ||
                         match.languageName?.simpleText ||
                         (typeof match.languageName === 'string' ? match.languageName : 'English');

            return {
                languageCode: match.languageCode,
                languageName: name
            };
        }

        return {
            languageCode: targetLang,
            languageName: 'English'
        };
    }

    function getCCButton(player) {
        const selector = '.ytp-subtitles-button, button[aria-keyshortcuts="c"]';
        return player?.querySelector?.(selector) || document.querySelector(selector);
    }

    function isCaptionsActive(player) {
        try {
            const ccButton = getCCButton(player);
            if (ccButton) {
                return ccButton.getAttribute('aria-pressed') === 'true';
            }
            const track = player?.getOption?.('captions', 'track');
            return Boolean(track && Object.keys(track).length && track.languageCode);
        } catch {
            return false;
        }
    }

    function getCaptionStateSnapshot(player) {
        if (!player) return '';
        try {
            return JSON.stringify({
                track: player.getOption?.('captions', 'track') || {},
                trans: player.getOption?.('captions', 'translationLanguage') || {},
                cc: getCCButton(player)?.getAttribute('aria-pressed') || null
            });
        } catch {
            return '';
        }
    }

    function executeTurnOff(player) {
        isScriptApplying = true;
        try {
            try {
                player.setOption('captions', 'translationLanguage', {});
                player.setOption('captions', 'track', {});
                player.toggleSubtitlesOff?.();
            } catch {}

            const ccButton = getCCButton(player);
            if (ccButton && ccButton.getAttribute('aria-pressed') === 'true') {
                ccButton.click();
            }
            lastKnownCaptionState = getCaptionStateSnapshot(player);
        } finally {
            isScriptApplying = false;
        }
    }

    function turnOffCaptions(player, activeVideoId = '', immediate = false) {
        clearMountTimer();
        executeTurnOff(player);

        // Re-verify after settle delay in case YouTube's player init auto-restores captions
        if (activeVideoId && !immediate) {
            mountTimer = setTimeout(() => {
                mountTimer = null;
                if (player.getVideoData?.()?.video_id !== activeVideoId) return;
                if (CONFIG.RESPECT_MANUAL_OVERRIDE && activeVideoId === manualOverrideVideoId) return;
                executeTurnOff(player);
            }, CONFIG.CHANGE_DELAY);
        }
    }

    function applyCaptionsWithMount(player, track, translationObj = null, activeVideoId = '', immediate = false) {
        clearMountTimer();

        const trackPayload = {
            languageCode: track.languageCode,
            ...(track.vssId ? { vssId: track.vssId } : {})
        };

        const apply = () => {
            if (activeVideoId && player.getVideoData?.()?.video_id !== activeVideoId) return;
            if (CONFIG.RESPECT_MANUAL_OVERRIDE && activeVideoId && activeVideoId === manualOverrideVideoId) return;

            isScriptApplying = true;
            try {
                try {
                    if (translationObj) {
                        player.setOption('captions', 'track', { ...trackPayload, translationLanguage: translationObj });
                        player.setOption('captions', 'translationLanguage', translationObj);
                    } else {
                        player.setOption('captions', 'translationLanguage', {});
                        player.setOption('captions', 'track', trackPayload);
                    }
                } catch {}

                const ccButton = getCCButton(player);
                if (ccButton) {
                    if (ccButton.getAttribute('aria-pressed') !== 'true') {
                        ccButton.click();
                    }
                } else {
                    try { player.toggleSubtitlesOn?.(); } catch {}
                }
                lastKnownCaptionState = getCaptionStateSnapshot(player);
            } finally {
                isScriptApplying = false;
            }
        };

        if (immediate) {
            apply();
            return;
        }

        mountTimer = setTimeout(() => {
            mountTimer = null;
            apply();
        }, CONFIG.CHANGE_DELAY);
    }

    function pickBestBaseTrackForTranslation(tracks) {
        const translatable = tracks.filter(t => t.isTranslatable !== false);
        if (!translatable.length) return null;

        return translatable.find(t => t.isDefault && !isAutoGenerated(t)) ||
               translatable.find(t => !isAutoGenerated(t)) ||
               translatable.find(t => t.isDefault) ||
               translatable[0];
    }

    function markManualOverride(videoId) {
        if (!CONFIG.RESPECT_MANUAL_OVERRIDE || !videoId) return;
        manualOverrideVideoId = videoId;
        processedVideoId = videoId;
        clearMountTimer();
        clearPollInterval();
        log(`Manual caption override detected for ${videoId}. Stepping aside for this video.`);
    }

    function selectPriorityTrack(tracks) {
        if (!Array.isArray(CONFIG.PRIORITY)) return null;
        for (let i = 0; i < CONFIG.PRIORITY.length; i++) {
            const rule = CONFIG.PRIORITY[i];
            const match = findMatchingTrack(tracks, rule);
            if (match) {
                return { track: match, rule };
            }
        }
        return null;
    }

    function checkChannelAndMusicDisable(player, playerVideoId, isMuted = false) {
        const checkChannelRules = CONFIG.CHANNEL_WHITELIST?.enabled || CONFIG.CHANNEL_BLACKLIST?.enabled;
        const channelInfo = checkChannelRules ? getVideoChannelInfo(player, playerVideoId) : null;
        const isWhitelisted = Boolean(CONFIG.CHANNEL_WHITELIST?.enabled && matchesChannelList(channelInfo, CONFIG.CHANNEL_WHITELIST.channels));

        if (isWhitelisted) {
            log(`Channel [${channelInfo.author || channelInfo.handle || channelInfo.channelId}] is whitelisted. Bypassing auto-disable rules.`);
            return { disabled: false, isWhitelisted: true };
        }

        if (CONFIG.CHANNEL_BLACKLIST?.enabled && matchesChannelList(channelInfo, CONFIG.CHANNEL_BLACKLIST.channels)) {
            log(`Channel [${channelInfo.author || channelInfo.handle || channelInfo.channelId}] is blacklisted. Turning captions off.`);
            return { disabled: true, isWhitelisted: false };
        }

        if (CONFIG.DISABLE_ON_MUSIC && !isMuted && isMusicVideo(player, playerVideoId)) {
            log(`Video [${playerVideoId}] is recognized as a Music Video. Turning captions off.`);
            return { disabled: true, isWhitelisted: false };
        }

        return { disabled: false, isWhitelisted: false };
    }

    function applyCaptionPreference(player, immediate = false) {
        if (!player || typeof player.getOption !== 'function') return false;

        hookPlayerEvents(player);

        const targetId = getTargetVideoId();
        const playerVideoId = player.getVideoData?.()?.video_id;

        if (!playerVideoId || (targetId && playerVideoId !== targetId)) {
            return false;
        }

        if (CONFIG.RESPECT_MANUAL_OVERRIDE && playerVideoId === manualOverrideVideoId) {
            return true;
        }

        if (playerVideoId === processedVideoId) return true;

        // 0. Shorts Auto-Disable Check
        if (isShortsDisabled()) {
            processedVideoId = playerVideoId;
            log('Captions disabled on Shorts. Turning captions off.');
            turnOffCaptions(player, playerVideoId, immediate);
            return true;
        }

        const isMuted = Boolean(CONFIG.SMART_MUTE && isPlayerMuted(player));
        lastMuteState = isPlayerMuted(player);
        if (isMuted) {
            smartMuteTurnedCaptionsOn = true;
        }

        // 1. Channel Whitelist / Blacklist & Music Video Checks
        const { disabled, isWhitelisted } = checkChannelAndMusicDisable(player, playerVideoId, isMuted);
        if (disabled) {
            processedVideoId = playerVideoId;
            turnOffCaptions(player, playerVideoId, immediate);
            return true;
        }

        // 2. No Captions Available Check
        if (hasNoCaptionsAvailable(player, playerVideoId)) {
            processedVideoId = playerVideoId;
            log(`Video ${playerVideoId} has no captions. Turning off.`);
            turnOffCaptions(player, playerVideoId, immediate);
            return true;
        }

        // 3. Retrieve Caption Tracks (needed for priority matching and ASR-based audio language detection)
        const tracks = getAvailableTracks(player, playerVideoId);
        if (!tracks.length) {
            return false;
        }

        // 4. Native Language Auto-Disable Check (bypassed if whitelisted or Smart Mute is active & muted)
        if (!isWhitelisted && CONFIG.NATIVE_LANG_AUTO_DISABLE?.enabled && !isMuted) {
            const audioLang = getVideoAudioLanguage(player, playerVideoId, tracks);
            if (isNativeAudioLanguage(audioLang, CONFIG.NATIVE_LANG_AUTO_DISABLE.languages)) {
                processedVideoId = playerVideoId;
                log(`Video audio is in native language [${audioLang}]. Turning captions off.`);
                turnOffCaptions(player, playerVideoId, immediate);
                return true;
            }
        }

        processedVideoId = playerVideoId;
        log(`Tracks detected for ${playerVideoId}:`, tracks);

        // 5. Evaluate priority rules dynamically in order
        const priorityMatch = selectPriorityTrack(tracks);
        if (priorityMatch) {
            const { track, rule } = priorityMatch;
            const ruleLabel = rule.name || `${rule.lang}${typeof rule.autoGenerated === 'boolean' ? (rule.autoGenerated ? ' (Auto)' : ' (Manual)') : ''}`;
            log(`Activating Priority [${ruleLabel}]`);
            applyCaptionsWithMount(player, track, null, playerVideoId, immediate);
            return true;
        }

        // 6. Fall back to Auto-Translate if configured
        const baseTrack = CONFIG.AUTO_TRANSLATE_TARGET ? pickBestBaseTrackForTranslation(tracks) : null;
        const translationObj = baseTrack ? getTranslationLanguageObject(player, playerVideoId, CONFIG.AUTO_TRANSLATE_TARGET) : null;

        if (baseTrack && translationObj) {
            log(`Activating Auto-Translate to [${translationObj.languageCode}] using base track:`, baseTrack);
            applyCaptionsWithMount(player, baseTrack, translationObj, playerVideoId, immediate);
        } else {
            log('No matching priority captions or auto-translate target available. Turning captions off.');
            turnOffCaptions(player, playerVideoId, immediate);
        }

        return true;
    }

    function scheduleCaptionCheck() {
        clearPollInterval();

        if (!isWatchPage()) return;

        const targetId = getTargetVideoId();
        if (targetId && targetId !== lastTargetVideoId) {
            lastTargetVideoId = targetId;
            resetVideoState();
        }

        if (CONFIG.RESPECT_MANUAL_OVERRIDE && targetId && targetId === manualOverrideVideoId) {
            return;
        }

        const player = getPlayer(targetId);
        const currentVideoId = player?.getVideoData?.()?.video_id;

        if (currentVideoId && currentVideoId === processedVideoId && (!targetId || currentVideoId === targetId)) {
            return;
        }

        let attempts = 0;
        pollInterval = setInterval(() => {
            const activePlayer = getPlayer(targetId);
            if (!activePlayer) return;

            const isAd = activePlayer.classList?.contains('ad-showing') ||
                         activePlayer.classList?.contains('ad-interrupting') ||
                         (activePlayer.adState && activePlayer.adState > 0);
            if (isAd) return;

            const activeId = activePlayer.getVideoData?.()?.video_id;
            if (targetId && activeId !== targetId) {
                return;
            }

            attempts++;

            const completed = applyCaptionPreference(activePlayer);

            if (completed || attempts >= CONFIG.MAX_ATTEMPTS) {
                clearPollInterval();

                if (!completed && attempts >= CONFIG.MAX_ATTEMPTS && activeId) {
                    processedVideoId = activeId;
                    log(`Polling timed out for ${activeId}. Turning captions off.`);
                    turnOffCaptions(activePlayer, activeId);
                }
            }
        }, 300);
    }

    const onNavigation = () => {
        lastTargetVideoId = '';
        lastObservedUrl = location.href;
        resetVideoState();
        scheduleCaptionCheck();
    };

    // Detect real user clicks on CC button or any player menu item that changes caption state
    document.addEventListener('click', (e) => {
        if (!e.isTrusted || !CONFIG.RESPECT_MANUAL_OVERRIDE || !isWatchPage()) return;

        const targetId = getTargetVideoId();
        const player = getPlayer(targetId);
        const videoId = player?.getVideoData?.()?.video_id || targetId;
        if (!videoId) return;

        if (e.target.closest?.('.ytp-subtitles-button, button[aria-keyshortcuts="c"]')) {
            smartMuteTurnedCaptionsOn = false;
            markManualOverride(videoId);
            return;
        }

        // Exclude volume controls and playback toggles from triggering manual override
        if (e.target.closest?.('.ytp-mute-button, .ytp-volume-panel, .ytp-volume-slider, .ytp-volume-control, .ytp-play-button, .ytp-progress-bar')) {
            return;
        }

        // Class-independent settings check: any trusted click inside the player that alters caption state
        if (player && player.contains?.(e.target)) {
            const prevState = getCaptionStateSnapshot(player);
            setTimeout(() => {
                if (isScriptApplying || isVolumeOrMuteChanging) return;
                const nextState = getCaptionStateSnapshot(player);
                if (prevState && nextState && prevState !== nextState) {
                    smartMuteTurnedCaptionsOn = false;
                    markManualOverride(videoId);
                }
            }, 100);
        }
    }, true);

    // Detect real user pressing 'c' shortcut to toggle captions
    document.addEventListener('keydown', (e) => {
        if (!e.isTrusted || !CONFIG.RESPECT_MANUAL_OVERRIDE || !isWatchPage()) return;
        if (e.ctrlKey || e.altKey || e.metaKey || e.shiftKey) return;
        if (e.key.toLowerCase() !== 'c') return;

        const el = e.target;
        if (el && (el.isContentEditable || el.matches?.('input, textarea, select'))) {
            return;
        }

        const targetId = getTargetVideoId();
        const player = getPlayer(targetId);
        const videoId = player?.getVideoData?.()?.video_id || targetId;
        if (videoId) {
            smartMuteTurnedCaptionsOn = false;
            markManualOverride(videoId);
        }
    }, true);

    function handleVolumeOrMuteChange(eventData) {
        if (!CONFIG.SMART_MUTE || !isWatchPage() || isShortsDisabled()) return;

        const targetId = getTargetVideoId();
        const player = getPlayer(targetId);
        if (!player) return;

        const videoId = player.getVideoData?.()?.video_id;
        if (!videoId) return;

        let isMuted;
        if (eventData && typeof eventData.muted === 'boolean') {
            isMuted = eventData.muted || eventData.volume === 0;
        } else {
            isMuted = isPlayerMuted(player);
        }

        if (lastMuteState === null) {
            lastMuteState = isMuted;
            return;
        }

        if (lastMuteState === isMuted) {
            return;
        }

        lastMuteState = isMuted;
        log(`Mute/Volume state changed to ${isMuted ? 'MUTED' : 'UNMUTED'}. Re-evaluating captions.`);

        isVolumeOrMuteChanging = true;
        try {
            if (isMuted) {
                const captionsActive = isCaptionsActive(player);
                if (!captionsActive) {
                    smartMuteTurnedCaptionsOn = true;
                }
                processedVideoId = '';
                applyCaptionPreference(player, true);
            } else {
                if (smartMuteTurnedCaptionsOn) {
                    smartMuteTurnedCaptionsOn = false;
                    processedVideoId = videoId;
                    log(`Unmuted: restoring captions to OFF (activated by Smart Mute).`);
                    turnOffCaptions(player, videoId, true);
                } else {
                    processedVideoId = '';
                    applyCaptionPreference(player, true);
                }
            }
        } finally {
            setTimeout(() => {
                isVolumeOrMuteChanging = false;
            }, 150);
        }
    }

    function handlePlayerApiChange(player) {
        if (isScriptApplying || isVolumeOrMuteChanging || !CONFIG.RESPECT_MANUAL_OVERRIDE || !isWatchPage()) return;
        const videoId = player?.getVideoData?.()?.video_id;
        if (!videoId || videoId !== processedVideoId || videoId === manualOverrideVideoId) return;

        const currentState = getCaptionStateSnapshot(player);
        if (lastKnownCaptionState && currentState && currentState !== lastKnownCaptionState) {
            smartMuteTurnedCaptionsOn = false;
            markManualOverride(videoId);
        }
    }

    function hookPlayerEvents(player) {
        if (!player || hookedPlayers.has(player) || typeof player.addEventListener !== 'function') return;
        hookedPlayers.add(player);
        try {
            player.addEventListener('onVolumeChange', handleVolumeOrMuteChange);
            player.addEventListener('onApiChange', () => handlePlayerApiChange(player));
        } catch {}
    }

    // React dynamically to mute / volume changes when SMART_MUTE is enabled
    document.addEventListener('volumechange', () => handleVolumeOrMuteChange(), true);

    window.addEventListener('yt-navigate-finish', onNavigation);
    document.addEventListener('yt-player-updated', scheduleCaptionCheck);
    document.addEventListener('yt-page-data-updated', scheduleCaptionCheck);
    window.addEventListener('popstate', scheduleCaptionCheck);

    if ('navigation' in window) {
        window.navigation.addEventListener('navigatesuccess', scheduleCaptionCheck);
    }

    // Browser-agnostic SPA URL change fallback (covers Firefox/Safari if yt-* events change)
    const titleTarget = document.querySelector('title') || document.head;
    if (titleTarget) {
        new MutationObserver(() => {
            if (location.href !== lastObservedUrl) {
                lastObservedUrl = location.href;
                scheduleCaptionCheck();
            }
        }).observe(titleTarget, { childList: true, subtree: true, characterData: true });
    }

    scheduleCaptionCheck();
})();
